package dragonboat

import (
	"fmt"
	"testing"

	"github.com/lni/dragonboat/v3/internal/rsm"
)

// TestAssuranceSnapshotRequestOutcome probes the completion contract of a
// user-requested snapshot: a request that is never reported back is expected to
// end with a timeout once the logical clock passes its deadline, after which the
// object accepts a new request that can be completed normally.
func TestAssuranceSnapshotRequestOutcome(t *testing.T) {
	errName := func(err error) string {
		if err == nil {
			return "nil"
		}
		return err.Error()
	}
	snapshotC := make(chan rsm.SSRequest, 4)
	p := newPendingSnapshot(snapshotC)

	req, err := p.request(rsm.UserRequested, "", false, 0, 5)
	fmt.Printf("CA_EVENT {\"event\":\"snapshot_request\",\"case\":\"expired\",\"err\":%q,\"queued\":%d,\"state_returned\":%t}\n",
		errName(err), len(snapshotC), req != nil)
	if req != nil {
		select {
		case r := <-req.CompletedC:
			fmt.Printf("CA_EVENT {\"event\":\"snapshot_early\",\"got\":%q}\n", r.code.String())
		default:
			fmt.Printf("CA_EVENT {\"event\":\"snapshot_early\",\"got\":\"none\"}\n")
		}
		p.tick(20)
		p.gc()
		select {
		case r := <-req.CompletedC:
			fmt.Printf("CA_EVENT {\"event\":\"snapshot_expired\",\"got\":%q,\"result_value\":%d}\n",
				r.code.String(), r.result.Value)
		default:
			fmt.Printf("CA_EVENT {\"event\":\"snapshot_expired\",\"got\":\"none\"}\n")
		}
	}

	req2, err := p.request(rsm.UserRequested, "", false, 0, 5)
	fmt.Printf("CA_EVENT {\"event\":\"snapshot_request\",\"case\":\"completed\",\"err\":%q,\"queued\":%d,\"state_returned\":%t}\n",
		errName(err), len(snapshotC), req2 != nil)
	if req2 != nil {
		var key uint64
		stale := 0
		for {
			select {
			case ssreq := <-snapshotC:
				if ssreq.Key == req2.key {
					key = ssreq.Key
				} else {
					stale++
				}
				continue
			default:
			}
			break
		}
		matched := key != 0 && key == req2.key
		p.apply(key, false, false, 42)
		select {
		case r := <-req2.CompletedC:
			fmt.Printf("CA_EVENT {\"event\":\"snapshot_completed\",\"key_matched\":%t,\"stale_requests\":%d,\"got\":%q,\"result_value\":%d}\n",
				matched, stale, r.code.String(), r.result.Value)
		default:
			fmt.Printf("CA_EVENT {\"event\":\"snapshot_completed\",\"key_matched\":%t,\"stale_requests\":%d,\"got\":\"none\"}\n",
				matched, stale)
		}
	}

	_, err = p.request(rsm.UserRequested, "", false, 0, 0)
	fmt.Printf("CA_EVENT {\"event\":\"snapshot_request\",\"case\":\"zero_timeout\",\"err\":%q}\n", errName(err))
}

package dragonboat

import (
	"fmt"
	"testing"

	"github.com/lni/dragonboat/v3/config"
	"github.com/lni/dragonboat/v3/internal/rsm"
	"github.com/lni/dragonboat/v3/internal/vfs"
	pb "github.com/lni/dragonboat/v3/raftpb"
)

func assuranceCCEntry(t *testing.T, index uint64, cc pb.ConfigChange) pb.Entry {
	t.Helper()
	data, err := cc.Marshal()
	if err != nil {
		t.Fatalf("failed to marshal config change %v", err)
	}
	return pb.Entry{Index: index, Term: 1, Type: pb.ConfigChangeEntry, Cmd: data}
}

// TestAssuranceWitnessRecordFromMembership lets the replicated state machine
// build its membership from configuration-change entries - first the cluster's
// only voting member, then the local node as a witness - and then reads back
// what node.notifyConfigChange stores and what node.getClusterInfo reports.
func TestAssuranceWitnessRecordFromMembership(t *testing.T) {
	fs := vfs.GetTestFS()
	cfg := config.Config{ClusterID: 1, NodeID: 2}
	n := &node{
		clusterID:    1,
		nodeID:       2,
		config:       cfg,
		initializedC: make(chan struct{}),
		sysEvents:    &sysEventListener{},
	}
	n.sm = rsm.NewStateMachine(
		rsm.NewNativeSM(cfg, &rsm.InMemStateMachine{}, nil),
		nil, cfg, &testDummyNodeProxy{}, fs)

	n.sm.TaskQ().Add(rsm.Task{Entries: []pb.Entry{
		assuranceCCEntry(t, 1, pb.ConfigChange{
			Type: pb.AddNode, NodeID: 1, Address: "a1", ConfigChangeId: 0,
		}),
		assuranceCCEntry(t, 2, pb.ConfigChange{
			Type: pb.AddWitness, NodeID: 2, Address: "a2", ConfigChangeId: 1,
		}),
	}})
	if _, err := n.sm.Handle(nil, nil); err != nil {
		t.Fatalf("failed to apply config changes %v", err)
	}
	m := n.sm.GetMembership()
	_, localIsWitness := m.Witnesses[2]
	fmt.Printf("CA_EVENT {\"event\":\"membership\",\"addresses\":%d,\"witnesses\":%d,\"local_is_witness\":%t,\"config_change_id\":%d}\n",
		len(m.Addresses), len(m.Witnesses), localIsWitness, m.ConfigChangeId)

	n.notifyConfigChange()
	stored, ok := n.clusterInfo.Load().(*ClusterInfo)
	if !ok || stored == nil {
		t.Fatalf("no cluster record stored")
	}
	fmt.Printf("CA_EVENT {\"event\":\"stored\",\"is_witness\":%t,\"is_observer\":%t,\"config_index\":%d,\"node_count\":%d}\n",
		stored.IsWitness, stored.IsObserver, stored.ConfigChangeIndex, len(stored.Nodes))

	reported := n.getClusterInfo()
	fmt.Printf("CA_EVENT {\"event\":\"reported\",\"is_witness\":%t,\"is_observer\":%t,\"pending\":%t,\"config_index\":%d,\"node_count\":%d}\n",
		reported.IsWitness, reported.IsObserver, reported.Pending,
		reported.ConfigChangeIndex, len(reported.Nodes))
}

