// TestAssuranceSnapshotInstallFrontier drives node.pushSnapshot and
// node.entriesToApply, then reads the first task the state machine reports to
// the apply loop, to see how a snapshot install moves the pushed/applied
// frontier and how committed entries around that frontier are treated.
func TestAssuranceSnapshotInstallFrontier(t *testing.T) {
	fs := vfs.GetTestFS()
	cfg := config.Config{ClusterID: 1, NodeID: 1}
	n := &node{
		clusterID:    1,
		nodeID:       1,
		config:       cfg,
		initializedC: make(chan struct{}),
		sysEvents:    &sysEventListener{},
		ss:           &snapshotState{},
		pipeline:     &assuranceNoopPipeline{},
	}
	n.sm = rsm.NewStateMachine(
		rsm.NewNativeSM(cfg, &rsm.InMemStateMachine{}, nil),
		nil, cfg, &testDummyNodeProxy{}, fs)
	n.toApplyQ = n.sm.TaskQ()

	ss := pb.Snapshot{Index: 5, Term: 2}
	n.pushSnapshot(ss, 0)
	fmt.Printf("CA_EVENT {\"event\":\"pushed\",\"pushed_index\":%d,\"ss_index\":%d}\n",
		n.pushedIndex, n.ss.getIndex())

	got := n.entriesToApply([]pb.Entry{
		{Index: 3, Term: 2},
		{Index: 4, Term: 2},
		{Index: 5, Term: 2},
		{Index: 6, Term: 2},
	})
	first := uint64(0)
	if len(got) > 0 {
		first = got[0].Index
	}
	fmt.Printf("CA_EVENT {\"event\":\"filtered\",\"count\":%d,\"first_index\":%d}\n",
		len(got), first)

	n.pushEntries(got)
	task, err := n.handleTask(nil, nil)
	if err != nil {
		t.Fatalf("handleTask returned %v", err)
	}
	fmt.Printf("CA_EVENT {\"event\":\"first_task\",\"recover\":%t,\"index\":%d}\n",
		task.Recover, task.Index)

	hole := func() (panicked bool) {
		defer func() {
			if r := recover(); r != nil {
				panicked = true
			}
		}()
		n.entriesToApply([]pb.Entry{{Index: 8, Term: 2}})
		return false
	}()
	fmt.Printf("CA_EVENT {\"event\":\"hole\",\"panicked\":%t}\n", hole)
}

package dragonboat

import (
	"fmt"
	"os"
	"os/exec"
	"strings"
	"testing"
	"time"

	"github.com/lni/goutils/syncutil"
)

const assurancePanicChildEnv = "CA_WORKER_PANIC_CHILD"

// TestAssuranceWorkerPanicOutcome runs the same stopper launch the engine's
// snapshot workers use, with a worker function that panics, in a child process
// so that the parent can report what happened to the process as a whole.
func TestAssuranceWorkerPanicOutcome(t *testing.T) {
	if os.Getenv(assurancePanicChildEnv) == "1" {
		stopper := syncutil.NewStopper()
		stopper.RunWorker(func() {
			fmt.Println("CA_EVENT {\"event\":\"child_worker_started\"}")
			panic("assurance worker panic")
		})
		time.Sleep(500 * time.Millisecond)
		fmt.Println("CA_EVENT {\"event\":\"child_survived\"}")
		stopper.Stop()
		return
	}

	cmd := exec.Command(os.Args[0],
		"-test.run", "TestAssuranceWorkerPanicOutcome", "-test.v")
	cmd.Env = append(os.Environ(), assurancePanicChildEnv+"=1")
	out, err := cmd.CombinedOutput()
	text := string(out)
	started := strings.Contains(text, "child_worker_started")
	survived := strings.Contains(text, "child_survived")
	panicked := strings.Contains(text, "panic: assurance worker panic")
	exitCode := 0
	if err != nil {
		if ee, ok := err.(*exec.ExitError); ok {
			exitCode = ee.ExitCode()
		} else {
			fmt.Printf("CA_EVENT {\"event\":\"spawn_failed\",\"error\":%q}\n", err.Error())
			return
		}
	}
	fmt.Printf("CA_EVENT {\"event\":\"child_result\",\"worker_started\":%t,\"survived\":%t,\"panicked\":%t,\"exit_code\":%d}\n",
		started, survived, panicked, exitCode)
}
